16 |     /**
17 |      * Convert spacing field to Tailwind airy utility
18 |      * 
19 |      * @return string Tailwind padding classes
20 |      */
21 |     public function toAiry(): string
22 |     {
23 |         $value = $this->value();
24 |         if (empty($value)) {
25 |             return 'py-airy-md'; // Default fallback
26 |         }
27 |         
28 |         return "pt-airy-{$value} pb-airy-{$value}";
29 |     }
