31 |     /**
32 |      * Inject Lucide SVG icon
33 |      * 
34 |      * @return string Raw SVG markup
35 |      */
36 |     public function toIcon(): string
37 |     {
38 |         $iconName = $this->value();
39 |         if (empty($iconName)) {
40 |             return '';
41 |         }
42 |         
43 |         // Load from lucide icon directory
44 |         $iconPath = kirby()->root('assets') . "/icons/{$iconName}.svg";
45 |         
46 |         if (file_exists($iconPath)) {
47 |             return file_get_contents($iconPath);
48 |         }
49 |         
50 |         return "<!-- Icon not found: {$iconName} -->";
51 |     }
52 | 
53 |     /**
54 |      * Convert theme field to Tailwind flood classes
55 |      * 
56 |      * @return string Background and text color classes
57 |      */
58 |     public function toTheme(): string
59 |     {
60 |         $theme = $this->value();
61 |         
62 |         return match($theme) {
63 |             'oceanic' => 'bg-oceanic-dark text-canvas',
64 |             'gold' => 'bg-warm-gold text-ink',
65 |             'light' => 'bg-canvas text-ink',
66 |             'dark' => 'bg-ink text-canvas',
67 |             default => 'bg-canvas text-ink',
68 |         };
69 |     }
